  for (const [x, y, w, h] of [[7, 0, 2, 6], [0, 6, 7, 2], [5, 8, 2, 5], [13, 6, 1, 5], [7, 11, 7, 2], [9, 4, 7, 2]]) ctx.fillRect(x, y, w, h);
  ctx.fillStyle = '#ffd23a';
