// ---- Stairs and slabs: names, crafting ----
STEP_MATERIALS.forEach((m, mi) => {
  for (let k = 0; k < 10; k++) {
    const id = STAIR_FIRST + mi * STAIR_STRIDE + k;
    const shown = k === 0 || k === 8; // the same block placed other ways is one item
    ITEM_INFO[id] = { name: `${m.name} ${k < 8 ? 'Stairs' : 'Slab'}`, color: m.color, hidden: !shown, ...(shown ? { lore: [k === 0 ? 'Place it facing the way you walk up. Next to other stairs it turns corners.' : 'Click the top or bottom half. Two slabs make a whole block.'] } : {}) };
  }
  RECIPES.push({ id: `${m.key}_stairs`, name: `${m.name} Stairs`, pattern: [m.base, null, null, m.base, m.base, null, m.base, m.base, m.base], width: 3, height: 3, output: { id: stairId(mi, 0, false), count: 4 }, needsTable: true });
  RECIPES.push({ id: `${m.key}_slab`, name: `${m.name} Slab`, pattern: [m.base, m.base, m.base], width: 3, height: 1, output: { id: slabId(mi, false), count: 6 }, needsTable: true });
});

// Item descriptions are only for special items: the Time Core, VibeBlox's own rare items (and the player head's skin name).
// Everything else (tools, redstone, food, blocks, spawn eggs...) has just its name. Mod items bring their own descriptions when they load.
const LORE_ITEMS = new Set(['Time Core', 'Infernium Ingot', 'Hollow Star', 'Cinderbone Skull', 'Bridge Egg', 'Selection Wand', 'Player Head']);
for (const key of Object.keys(ITEM_INFO)) { const info = ITEM_INFO[Number(key)]; if (info.lore && !LORE_ITEMS.has(info.name)) delete info.lore; }

/**
 * Match a crafting grid against the recipe list. `grid` is row-major with
 * `size`x`size` cells (2 for the inventory grid, 3 for the table); null =
 * empty. Patterns are matched at every valid offset so a small recipe can
 * sit anywhere in a bigger grid, exactly like Minecraft's shaped crafting.
 */
Object.assign(SMELT_XP, {
  [ITEM_IRON_INGOT]: 0.7, [ITEM_GOLD_INGOT]: 1, [ITEM_INFERNIUM_INGOT]: 2, [BLOCK_GLASS]: 0.1, [ITEM_CHARCOAL]: 0.15,
  [ITEM_COOKED_PORKCHOP]: 0.35, [ITEM_STEAK]: 0.35, [ITEM_COOKED_CHICKEN]: 0.35,
});
for (const b of [BLOCK_COAL_ORE, BLOCK_DIAMOND_ORE, BLOCK_EMERALD_ORE, BLOCK_QUARTZ_ORE, BLOCK_LAPIS_ORE, BLOCK_REDSTONE_ORE]) FORTUNE_ORES.add(b);

