// ===================================================================
//  Chunk data — stores voxel IDs in a flat array
// ===================================================================

/** Which monster a spawner at this spot makes (the same for everyone: it comes from the position). */
export function spawnerKind(x: number, y: number, z: number): 'zombie' | 'skeleton' | 'spider' {
  const h = (Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(z, 83492791)) >>> 0;
  return (['zombie', 'skeleton', 'spider', 'zombie'] as const)[(h >>> 7) % 4];
}
class Chunk {
  cx: number;
  cz: number;
  blocks: Uint16Array;
  mesh: THREE.Mesh | null = null;
  fluidMesh: THREE.Mesh | null = null;
  generated = false;

  constructor(cx: number, cz: number) {
    this.cx = cx;
    this.cz = cz;
    this.blocks = new Uint16Array(CHUNK_SIZE * CHUNK_HEIGHT * CHUNK_SIZE);
  }

  idx(x: number, y: number, z: number): number {
    return (y * CHUNK_SIZE + z) * CHUNK_SIZE + x;
  }

  get(x: number, y: number, z: number): number {
    if (x < 0 || x >= CHUNK_SIZE || z < 0 || z >= CHUNK_SIZE || y < 0 || y >= CHUNK_HEIGHT) return BLOCK_AIR;
    return this.blocks[this.idx(x, y, z)];
  }

  /** Mob spawners placed in this chunk (local x, y, z): the game checks these while you are near. */
  spawners: Array<[number, number, number]> | null = null;

  set(x: number, y: number, z: number, v: number) {
    if (x < 0 || x >= CHUNK_SIZE || z < 0 || z >= CHUNK_SIZE || y < 0 || y >= CHUNK_HEIGHT) return;
    this.blocks[this.idx(x, y, z)] = v;
    if (v === BLOCK_SPAWNER && !this.spawners?.some((s) => s[0] === x && s[1] === y && s[2] === z)) (this.spawners ??= []).push([x, y, z]);
  }
}

// Extension of Chunk to support setting blocks in world coordinates that
// may land in a neighboring chunk. This handles cross-boundary tree leaves.

// ===================================================================
//  World — manages chunks, noise generation, and mesh building
// ===================================================================

type Biome = 'plains' | 'forest' | 'desert' | 'snowy' | 'mountains' | 'ocean' | 'nether' | 'custom' | 'taiga' | 'birch_forest' | 'dark_forest' | 'savanna' | 'badlands';
/** Badlands bands, top to bottom (repeats every 9 blocks). */
const BADLANDS_BANDS = [BLOCK_TERRACOTTA_ORANGE, BLOCK_TERRACOTTA, BLOCK_TERRACOTTA_YELLOW, BLOCK_TERRACOTTA, BLOCK_TERRACOTTA_WHITE, BLOCK_TERRACOTTA_ORANGE, BLOCK_TERRACOTTA, BLOCK_TERRACOTTA, BLOCK_TERRACOTTA_YELLOW];

/** A dimension a mod can create with game.dimensions.create(). */
export type DimensionSpec = {
  id: string; name: string; type: 'flat' | 'void' | 'islands' | 'caves' | 'hills' | 'mountains';
  top: number; filler: number; base: number; liquid: number; sky: string; fog: string; light: number;
  // Optional extras (scripts may leave any of them out):
  /** hills/mountains: the ground level (4-50), how tall the bumps are, and how wide (smaller = wider) */
  height?: number; amplitude?: number; scale?: number;
  /** liquid fills every hollow up to this height (-1: none) */
  waterLevel?: number;
  /** wood type for trees (0 oak, 1 birch, 2 spruce, 3 jungle; -1 none) and how often one grows (0-0.2 per block) */
  trees?: number; treeChance?: number;
  /** coal, iron, gold and diamond in the rock */
  ores?: boolean;
  /** blocks (flowers, tall grass...) dotted on the ground, and how often (0-0.5) */
  plants?: number[]; plantChance?: number;
  /** 1 = normal. 0.2 = the moon, 2 = heavy */
  gravity?: number;
  stars?: boolean; clouds?: boolean;
};
/** Where a dimension puts the ground at x,z (hills and mountains). */
export function customGroundHeight(noise: { fbm: (x: number, y: number, z: number, o: number, p: number, s: number) => number }, sp: DimensionSpec, wx: number, wz: number): number {
  const mountains = sp.type === 'mountains';
  const base = Math.max(4, Math.min(50, sp.height ?? (mountains ? 18 : 22)));
  const amp = Math.max(0, Math.min(40, sp.amplitude ?? (mountains ? 26 : 7)));
  const sc = Math.max(0.002, Math.min(0.2, sp.scale ?? (mountains ? 0.012 : 0.025)));
  const n = noise.fbm(wx, 0, wz, 4, 0.5, sc);
  const h = mountains ? base + Math.pow(Math.max(0, n * 0.7 + 0.5), 2.2) * amp * 1.6 : base + n * amp * 1.4;
  return Math.max(2, Math.min(CHUNK_HEIGHT - 9, Math.round(h)));
}
