  getFov: () => number;
  getInventory: () => Slots;
  getHealth: () => number;
  getHunger: () => number;
  onInventoryChange: (cb: (slots: Slots, offhand: ItemStack | null, armor: Slots) => void) => void;
  getArmor: () => Slots;
  setArmor: (armor: Slots) => void;
