  touchLook: (dx: number, dy: number) => void;
  touchPress: (button: 0 | 2, down: boolean) => void;
  setGameMode: (m: PlayMode) => void;
  getGameMode: () => PlayMode;
  teleport: (x: number, y: number, z: number) => void;
  clearInventory: () => void;
  kill: () => void;
  getDebugInfo: () => DebugInfo;
  getFps: () => number;
  closeInventory: () => void;
  onPlayerHurt: (cb: (amount: number) => void) => void;
  /** Fires when you catch fire or the flames go out (the screen shows burning flames at the bottom). */
